"""
    Test if a string is a hexadecimal in string representation.

    :param s: The string to test.
    :return: True if hexadecimal, False if not.
    """
def is_hex(s: Any) -> object {
    try {
        int(s, 16);
        return True;
    } except ValueError {
        return False;
    }
}

